// Build Apify Google Maps Scraper request body for B2B
// Docs: https://apify.com/apify/google-maps-scraper
const item = $input.first().json;
const queryParts = [item.industry, 'in', item.location];
if (item.keywords && item.keywords.trim()) queryParts.push(item.keywords.trim());
const query = queryParts.join(' ');

return [{
  json: {
    ...item,
    apify_body: JSON.stringify({
      searchStringsArray: [query],
      maxCrawledPlacesPerSearch: item.count,
      language: 'en',
      maxImages: 0,
      maxReviews: 0,
      includeHistograms: false,
      includeOpeningHours: false,
      scrapeContacts: true
    })
  }
}];

// Build Apify Yelp Scraper request body for B2C
// Docs: https://apify.com/yin/yelp-scraper
const item = $input.first().json;
const searchTerm = [item.industry, item.keywords].filter(Boolean).join(' ').trim() || item.industry;

return [{
  json: {
    ...item,
    apify_body: JSON.stringify({
      search: searchTerm,
      location: item.location,
      searchLimit: item.count,
      reviewLimit: 0,
      scrapeReviews: false
    })
  }
}];

// Normalize Google Maps B2B results into SignafyAI lead schema
const rawInput = $input.all();
const meta = $('Parse Input').first().json;

// Handle both: single item with array body, OR multiple items
let rawLeads;
if (rawInput.length === 1 && Array.isArray(rawInput[0].json)) {
  rawLeads = rawInput[0].json;
} else if (rawInput.length === 1 && rawInput[0].json && Array.isArray(rawInput[0].json.items)) {
  rawLeads = rawInput[0].json.items;
} else {
  rawLeads = rawInput.map(i => i.json).filter(Boolean);
}

rawLeads = rawLeads.slice(0, meta.count || 25);

function extractZip(str) {
  if (!str) return '';
  const m = str.match(/\b\d{5}(?:-\d{4})?\b/);
  return m ? m[0] : '';
}

function formatPhone(phone) {
  if (!phone) return '';
  const d = phone.replace(/\D/g, '');
  if (d.length === 10) return '(' + d.slice(0,3) + ') ' + d.slice(3,6) + '-' + d.slice(6);
  if (d.length === 11 && d[0] === '1') return '(' + d.slice(1,4) + ') ' + d.slice(4,7) + '-' + d.slice(7);
  return phone;
}

function extractDomain(website) {
  if (!website) return '';
  return website.replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
}

const now = new Date().toISOString();

return rawLeads.map((d, idx) => {
  const businessName = d.title || d.name || '';
  const zip = d.postalCode || extractZip(d.address || '');
  const phone = formatPhone(d.phone || d.phoneUnformatted || '');
  const website = d.website || '';

  // Extract owner name if present
  let firstName = '', lastName = '';
  const ownerRaw = d.ownerName || d.people?.[0]?.name || '';
  if (ownerRaw && ownerRaw.trim()) {
    const parts = ownerRaw.trim().split(/\s+/);
    if (parts.length >= 2) {
      firstName = parts[0];
      lastName = parts.slice(1).join(' ');
    }
  }

  // Emails sometimes returned by Google Maps scraper
  const emailRaw = (d.emails && d.emails[0]) || '';

  const score = Math.min(90, 50
    + Math.floor((d.reviewsCount || 0) / 10)
    + (phone ? 10 : 0)
    + (website ? 5 : 0)
    + (emailRaw ? 15 : 0)
  );

  return {
    json: {
      id: 'apify-gmaps-' + Date.now() + '-' + idx,
      first_name: firstName,
      last_name: lastName,
      name: (firstName && lastName) ? firstName + ' ' + lastName : businessName,
      company: businessName,
      email: emailRaw,
      phone: phone,
      zip: zip,
      website: website,
      domain: extractDomain(website),
      source: 'Google Maps',
      full_address: d.address || '',
      platform: 'google',
      lead_type: meta.lead_type || 'b2b',
      industry: meta.industry,
      location: meta.location,
      score: score,
      status: 'new',
      tags: ['b2b', 'scraped', 'google-maps'],
      notes: d.categoryName ? 'Category: ' + d.categoryName : null,
      // Carry metadata through
      run_id: meta.run_id,
      org_id: meta.org_id,
      user_email: meta.user_email,
      callback_url: meta.callback_url,
      last_activity: now,
      created_at: now,
      updated_at: now
    }
  };
});

// Normalize Yelp B2C results into SignafyAI lead schema
const rawInput = $input.all();
const meta = $('Parse Input').first().json;

let rawLeads;
if (rawInput.length === 1 && Array.isArray(rawInput[0].json)) {
  rawLeads = rawInput[0].json;
} else if (rawInput.length === 1 && rawInput[0].json && Array.isArray(rawInput[0].json.items)) {
  rawLeads = rawInput[0].json.items;
} else {
  rawLeads = rawInput.map(i => i.json).filter(Boolean);
}

rawLeads = rawLeads.slice(0, meta.count || 25);

function extractZip(str) {
  if (!str) return '';
  const m = str.match(/\b\d{5}(?:-\d{4})?\b/);
  return m ? m[0] : '';
}

function formatPhone(phone) {
  if (!phone) return '';
  const d = phone.replace(/\D/g, '');
  if (d.length === 10) return '(' + d.slice(0,3) + ') ' + d.slice(3,6) + '-' + d.slice(6);
  if (d.length === 11 && d[0] === '1') return '(' + d.slice(1,4) + ') ' + d.slice(4,7) + '-' + d.slice(7);
  return phone;
}

const now = new Date().toISOString();

return rawLeads.map((d, idx) => {
  const businessName = d.name || d.title || '';
  const zip = d.postalCode || d.zip || extractZip(d.fullAddress || d.address || '');
  const phone = formatPhone(d.phone || '');
  const website = d.website || d.url || '';

  // Owner name (Yelp sometimes exposes this)
  let firstName = '', lastName = '';
  const ownerRaw = d.ownerName || (d.businessOwner && d.businessOwner.name) || '';
  if (ownerRaw && ownerRaw.trim()) {
    const parts = ownerRaw.trim().split(/\s+/);
    if (parts.length >= 2) {
      firstName = parts[0];
      lastName = parts.slice(1).join(' ');
    }
  }

  const categories = Array.isArray(d.categories)
    ? d.categories.map(c => (typeof c === 'string' ? c : c.title || c.alias || '')).filter(Boolean).join(', ')
    : (typeof d.categories === 'string' ? d.categories : '');

  const score = Math.min(90, 50
    + Math.floor((d.reviewCount || d.reviewsCount || 0) / 20)
    + (phone ? 10 : 0)
  );

  const notes = [];
  if (d.rating) notes.push('Yelp: ' + d.rating + '★ (' + (d.reviewCount || 0) + ' reviews)');
  if (categories) notes.push('Categories: ' + categories);

  return {
    json: {
      id: 'apify-yelp-' + Date.now() + '-' + idx,
      first_name: firstName,
      last_name: lastName,
      name: (firstName && lastName) ? firstName + ' ' + lastName : businessName,
      company: businessName,
      email: '',
      phone: phone,
      zip: zip,
      website: website,
      domain: website.replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, ''),
      source: 'Yelp',
      full_address: d.fullAddress || d.address || '',
      platform: 'google',
      lead_type: meta.lead_type || 'b2c',
      industry: categories || meta.industry,
      location: meta.location,
      score: score,
      status: 'new',
      tags: ['b2c', 'scraped', 'yelp'],
      notes: notes.length ? notes.join(' | ') : null,
      // Carry metadata through
      run_id: meta.run_id,
      org_id: meta.org_id,
      user_email: meta.user_email,
      callback_url: meta.callback_url,
      last_activity: now,
      created_at: now,
      updated_at: now
    }
  };
});

// Build Airtable create-record body for this single lead item
const l = $input.item.json;
return {
  json: {
    ...l,
    airtable_body: JSON.stringify({
      records: [{
        fields: {
          'First Name': l.first_name || '',
          'Last Name': l.last_name || '',
          'Full Name': l.name || '',
          'Company': l.company || '',
          'Email': l.email || '',
          'Phone': l.phone || '',
          'Zip Code': l.zip || '',
          'Website': l.website || '',
          'Full Address': l.full_address || '',
          'Source': l.source || '',
          'Lead Type': (l.lead_type || '').toUpperCase(),
          'Industry': l.industry || '',
          'Location': l.location || '',
          'Status': 'New',
          'Score': l.score || 50,
          'Notes': l.notes || '',
          'Date Added': new Date().toISOString().split('T')[0],
          'Tags': (l.tags || []).join(', ')
        }
      }]
    })
  }
};

// Aggregate all leads, compute HMAC, build email HTML, prepare callback payload
const crypto = require('crypto');
const secret = process.env.N8N_HMAC_SECRET || 'dev-secret';

const all = $input.all();
const leads = all.map(i => i.json);

if (leads.length === 0) {
  throw new Error('No leads were scraped. Verify Apify actor IDs, API token, and search criteria.');
}

const meta = leads[0];
const callbackUrl = meta.callback_url || '';
const runId = meta.run_id || '';
const orgId = meta.org_id || '';
const userEmail = meta.user_email || '';
const leadType = (meta.lead_type || 'b2b').toUpperCase();

// Build SignafyAI-compatible lead objects
const signafyLeads = leads.map(l => ({
  id: l.id,
  org_id: orgId,
  name: l.name,
  company: l.company || null,
  email: l.email || null,
  phone: l.phone || null,
  platform: l.platform || 'google',
  source_url: null,
  industry: l.industry || null,
  location: l.location || null,
  notes: l.notes || null,
  tags: l.tags || [],
  score: l.score || 50,
  status: 'new',
  last_activity: new Date().toISOString(),
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
}));

// Callback payload
const callbackPayload = JSON.stringify({
  run_id: runId,
  workflow_type: 'lead_discovery',
  status: 'complete',
  org_id: orgId,
  leads: signafyLeads,
  output: { leads_found: signafyLeads.length, source: 'apify' }
});

const signature = crypto.createHmac('sha256', secret).update(callbackPayload).digest('hex');

// Build email HTML
const tableRows = leads.map(l => {
  const name = [l.first_name, l.last_name].filter(Boolean).join(' ') || l.name || '—';
  const emailLink = l.email
    ? '<a href="mailto:' + l.email + '" style="color:#7c3aed;text-decoration:none;">' + l.email + '</a>'
    : '—';
  return '<tr style="border-bottom:1px solid #f3f4f6;">' +
    '<td style="padding:10px 14px;color:#111827;font-size:13px;">' + name + '</td>' +
    '<td style="padding:10px 14px;color:#374151;font-size:13px;">' + (l.company || '—') + '</td>' +
    '<td style="padding:10px 14px;font-size:13px;">' + emailLink + '</td>' +
    '<td style="padding:10px 14px;color:#374151;font-size:13px;">' + (l.phone || '—') + '</td>' +
    '<td style="padding:10px 14px;color:#374151;font-size:13px;">' + (l.zip || '—') + '</td>' +
    '<td style="padding:10px 14px;color:#374151;font-size:13px;">' + (l.source || '—') + '</td>' +
    '</tr>';
}).join('');

const emailHtml = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
  '<body style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Helvetica Neue,Arial,sans-serif;background:#f3f4f6;padding:32px 16px;margin:0;">' +
  '<div style="max-width:900px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,.08);">' +
  '<div style="background:linear-gradient(135deg,#7c3aed 0%,#4f46e5 100%);padding:32px 40px;">' +
  '<img src="https://signafy-ai.vercel.app/logo.png" alt="SignafyAI" style="height:32px;margin-bottom:20px;" onerror="this.style.display=\'none\'"/>' +
  '<h1 style="margin:0;font-size:24px;font-weight:700;color:#ffffff;letter-spacing:-0.5px;">Your Leads Are Ready</h1>' +
  '<p style="margin:8px 0 0;font-size:14px;color:rgba(255,255,255,.8);">' + leads.length + ' ' + leadType + ' leads scraped and imported to your dashboard</p>' +
  '</div>' +
  '<div style="padding:32px 40px;overflow-x:auto;">' +
  '<table style="width:100%;border-collapse:collapse;">' +
  '<thead><tr style="background:#f9fafb;">' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Name</th>' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Company</th>' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Email</th>' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Phone</th>' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Zip</th>' +
  '<th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #e5e7eb;">Source</th>' +
  '</tr></thead>' +
  '<tbody>' + tableRows + '</tbody>' +
  '</table>' +
  '</div>' +
  '<div style="padding:24px 40px;background:#f9fafb;border-top:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;">' +
  '<p style="margin:0;font-size:12px;color:#9ca3af;">Generated by <strong style="color:#374151;">SignafyAI</strong></p>' +
  '<a href="https://signafy-ai.vercel.app/leads" style="display:inline-block;padding:10px 20px;background:#7c3aed;color:#fff;text-decoration:none;border-radius:8px;font-size:13px;font-weight:600;">View in Dashboard →</a>' +
  '</div>' +
  '</div></body></html>';

return [{
  json: {
    callback_url: callbackUrl,
    callback_payload: callbackPayload,
    signature: signature,
    to_email: userEmail,
    subject: '[SignafyAI] ' + leads.length + ' New ' + leadType + ' Leads Ready',
    html: emailHtml,
    run_id: runId,
    leads_count: leads.length
  }
}];

// Build error callback payload for SignafyAI
const crypto = require('crypto');
const secret = process.env.N8N_HMAC_SECRET || 'dev-secret';

const errData = $input.first().json;
const runId = errData.execution?.customData?.run_id || '';
const orgId = errData.execution?.customData?.org_id || '';
const callbackUrl = errData.execution?.customData?.callback_url || process.env.SIGNAFY_CALLBACK_URL || '';

const payload = JSON.stringify({
  run_id: runId,
  workflow_type: 'lead_discovery',
  status: 'failed',
  org_id: orgId,
  error_message: errData.error?.message || 'n8n workflow execution failed'
});

const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{ json: { callback_url: callbackUrl, payload, signature } }];
